import{_ as a,o as t,c as o,a1 as i}from"./chunks/framework.CiMD_7j0.js";const p=JSON.parse('{"title":"Operations & Troubleshooting","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"91e797e7-f5a1-46b9-b9e2-54a4f04c2561","PropagateID":"91e797e7-f5a1-46b9-b9e2-54a4f04c2561","ReservedCode1":"a540a9e3-69f7-4d8a-ad28-2e9d619413c3","ReservedCode2":"a540a9e3-69f7-4d8a-ad28-2e9d619413c3"}},"headers":[],"relativePath":"en/guide/go/operations.md","filePath":"en/guide/go/operations.md","lastUpdated":null}'),n={name:"en/guide/go/operations.md"};function r(s,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="operations-troubleshooting" tabindex="-1">Operations &amp; Troubleshooting <a class="header-anchor" href="#operations-troubleshooting" aria-label="Permalink to &quot;Operations &amp; Troubleshooting&quot;">​</a></h1><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>ApeAdmin-Gin uses Zap for structured JSON logs. Every request is assigned a unique ID by the <code>request_id</code> middleware, threading through the entire call chain. Operation logs are written through the async <code>auditqueue</code> and never block the main request.</p><p>MCP calls are audited automatically, recording request params, response results, latency and caller info — viewable in the admin panel.</p><p>When troubleshooting, check in order: startup logs, plugin status, the log entries for the RequestID, and the API responses in the browser Network tab.</p><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="menu-404" tabindex="-1">Menu 404 <a class="header-anchor" href="#menu-404" aria-label="Permalink to &quot;Menu 404&quot;">​</a></h3><p>Check that the menu <code>component</code> resolves to a <code>.vue</code> file of the same name under <code>frontend/src/views</code> (case-sensitive). Then sign out and reload the user menu.</p><h3 id="plugin-apis-missing" tabindex="-1">Plugin APIs Missing <a class="header-anchor" href="#plugin-apis-missing" aria-label="Permalink to &quot;Plugin APIs Missing&quot;">​</a></h3><p>Check whether the plugin <code>Register()</code> ran successfully and look at the plugin-loading stage in the startup logs. For L2 ZIP plugins, confirm the manifest format is correct. If needed, disable and re-enable.</p><h3 id="ai-chat-fails" tabindex="-1">AI Chat Fails <a class="header-anchor" href="#ai-chat-fails" aria-label="Permalink to &quot;AI Chat Fails&quot;">​</a></h3><p>Confirm the AI model API key and network access are configured in the admin panel; check the MCP gateway timeout (default 30s) and concurrency limit (default 10). Inspect the MCP audit logs for error details.</p><h3 id="assets-404" tabindex="-1">Assets 404 <a class="header-anchor" href="#assets-404" aria-label="Permalink to &quot;Assets 404&quot;">​</a></h3><p>Confirm the plugin is enabled and check the static file directory config (<code>app.spa_dir</code>) and route registration.</p><h2 id="production-checklist" tabindex="-1">Production Checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production Checklist&quot;">​</a></h2><ul><li>[ ] Change <code>jwt.secret</code>; otherwise the key circuit-breaker refuses to start (it detects the default secret when debug=false).</li><li>[ ] Adjust the database pool <code>max_open_conns</code> to match actual load.</li><li>[ ] Confirm the API rate limit (300/IP/min, burst 50) fits your needs.</li><li>[ ] Configure CORS Origins for your production domain.</li><li>[ ] Verify the graceful shutdown flow: plugin unload → event notification → log drain → DB disconnect.</li><li>[ ] Configure backup and access control for the <code>uploads/</code> directory.</li></ul>',16)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
